import{_ as o,c as t,o as d,ag as r}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"小程序","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/miniapps.md","filePath":"zh-CN/guide/miniapps.md","lastUpdated":1791311600000}'),a={name:"zh-CN/guide/miniapps.md"};function c(i,e,l,n,s,h){return d(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="小程序" tabindex="-1">小程序 <a class="header-anchor" href="#小程序" aria-label="Permalink to &quot;小程序&quot;">​</a></h1><p>nPlyr 可以运行 <strong>hikerView 兼容的小程序</strong>——也就是为 Android 应用提供动力的同一批社区规则。本页解释它们是什么，以及 nPlyr 如何执行它们。关于兼容性边界（尤其是 Java/Rhino 部分），请阅读<a href="/zh-CN/guide/miniapp-compatibility.html">兼容性</a>页面。</p><h2 id="什么是小程序" tabindex="-1">什么是小程序？ <a class="header-anchor" href="#什么是小程序" aria-label="Permalink to &quot;什么是小程序？&quot;">​</a></h2><p>在这个生态中，小程序是一个<strong>规则包</strong>（HTML + JavaScript），它告诉应用如何：</p><ul><li>渲染一个分类 / 频道的<strong>首页</strong>，</li><li>执行一次<strong>搜索</strong>，</li><li>解析一个<strong>列表</strong>页与一个<strong>详情</strong>页，并</li><li>提取<strong>可播放链接</strong>交给播放器。</li></ul><p>规则逻辑运行在 JavaScript 引擎中，并通过一个名为 <strong><code>fy_bridge_app</code></strong>（简称 <strong><code>fba</code></strong>）的桥接对象与宿主应用通信。</p><h2 id="nplyr-重实现的契约" tabindex="-1">nPlyr 重实现的契约 <a class="header-anchor" href="#nplyr-重实现的契约" aria-label="Permalink to &quot;nPlyr 重实现的契约&quot;">​</a></h2><p>nPlyr <strong>不</strong>移植 hikerView 的 Android/Java UI。相反，它复用了真正承载价值的层次——<strong>规则引擎、解析 DSL 与小程序桥接契约</strong>——并为 Apple 平台原生重写了 UI、WebView 与网络层。</p><p>具体而言，nPlyr 提供了以下内容的原生实现：</p><ul><li><strong>规则 DSL</strong>：<code>pdfh</code> / <code>pdfa</code> / <code>pd</code> 选择器、<code>parseDom</code>、<code>setHomeResult</code>、<code>setSearchResult</code>、<code>setResult</code>；</li><li><strong><code>$</code> 选择器兼容层</strong>，使 <code>$(url).lazyRule(fn)</code> 与 <code>$(url, ordinary).lazyRule</code> 表现得符合预期；</li><li><strong><code>fy_bridge_app</code> / <code>fba</code> 桥</strong>，使规则可以调用宿主功能：播放、fetch、post、解析、存储变量；</li><li><strong><code>hiker://</code> 伪协议</strong>路由（包括作为轻量参数载体的 <code>hiker://empty##…</code>，以及用于聚合搜索的 <code>hiker://search?s=</code>）；</li><li><strong><code>lazyRule</code> / <code>.rule(fn)</code></strong> 执行模型、页面导航（<code>beginResultNavigation</code> / <code>finalizeResultPage</code>）以及结果栈生命周期（<code>onClose</code> 归属、<code>MY_PAGE</code> 归属）。</li></ul><h2 id="规则-dsl-要点" tabindex="-1">规则 DSL 要点 <a class="header-anchor" href="#规则-dsl-要点" aria-label="Permalink to &quot;规则 DSL 要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>用途</th></tr></thead><tbody><tr><td><code>setHomeResult([…])</code></td><td>输出首页网格（分类 / 频道）。</td></tr><tr><td><code>setSearchResult([…])</code></td><td>输出搜索结果。</td></tr><tr><td><code>lazyRule</code> / <code>.rule(fn)</code></td><td>运行子规则以解析列表 / 详情页。</td></tr><tr><td><code>fetch</code> / <code>post</code></td><td>带请求头的 HTTP；<code>withHeaders</code> / <code>onlyHeaders</code> / <code>withStatusCode</code> 返回 JSON 信封。</td></tr><tr><td><code>putVar</code> / <code>getVar</code> / <code>putMyVar</code> / <code>getMyVar</code></td><td>内存变量；<code>setItem</code> / <code>getItem</code> / <code>clearItem</code> 持久化到本地存储。</td></tr><tr><td><code>MY_URL</code> / <code>MY_RULE</code></td><td>当前规则的 URL 与规则主体。</td></tr><tr><td><code>AES</code> / <code>RSA</code> / <code>CryptoJS</code></td><td>规则可用的加密辅助。</td></tr></tbody></table><p>每个列表条目都带有一个 <code>col_type</code>，nPlyr 将其映射到 SwiftUI 布局——共有 <strong>38 种 <code>col_type</code> 布局</strong>（如 <code>text_1</code>、<code>pic_19</code>），与 hikerView 自有的条目模板对齐，因此现有规则会如其作者所预期的那样渲染。</p><h2 id="管理小程序" tabindex="-1">管理小程序 <a class="header-anchor" href="#管理小程序" aria-label="Permalink to &quot;管理小程序&quot;">​</a></h2><p>打开<strong>小程序</strong>（macOS 上的管理器窗口；iOS 上的标签 / 页面）以：</p><ul><li>从分享文本或 JSON <strong>导入</strong>一个程序，</li><li><strong>添加 / 编辑</strong>一条规则（macOS 上是完整规则编辑器；iOS 上是一个 Push 页面），</li><li><strong>重排</strong>程序（拖拽）——首页顶行跟随该顺序，</li><li><strong>删除</strong>一个程序，</li><li><strong>分享 / 云分享</strong>一个程序（云后端：TextDB、<code>cmd.im</code> 302 重定向，以及 <code>pasteme</code>）。</li></ul><p><strong>免费层级</strong>会限制导入的小程序数量；一次性解锁会移除该限制。</p><h2 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h2><p>独立的搜索窗口由你已安装且声明了 <code>search_url</code> 的规则构建而成。你可以搜索单个引擎，也可以跨所有引擎聚合搜索。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/zh-CN/guide/miniapp-compatibility.html">兼容性</a>——具体哪些 Java/Rhino 行为被支持、哪些不被支持。</li><li><a href="/zh-CN/guide/downloads.html">下载与媒体库</a>——解析出的链接去向何处。</li><li><a href="/zh-CN/guide/browser.html">浏览器与嗅探器</a>——抓取链接的另一条路径。</li></ul><h2 id="海阔视界官方文档" tabindex="-1">海阔视界官方文档 <a class="header-anchor" href="#海阔视界官方文档" aria-label="Permalink to &quot;海阔视界官方文档&quot;">​</a></h2><p>nPlyr 旨在与 hikerView 规则生态兼容。关于完整的规则与小程序参考——DSL、选择器、桥接契约与编写指南——请参阅海阔视界官方文档：</p><ul><li><strong>海阔视界文档：</strong> <a href="https://github.com/ReflectionLab/Documents" target="_blank" rel="noreferrer">https://github.com/ReflectionLab/Documents</a></li></ul><p>如果你已经为 hikerView 编写规则，同样的分享文本与 JSON 在 nPlyr 中可直接导入并运行（受上述兼容性边界约束）。</p>',25)])])}const u=o(a,[["render",c]]);export{g as __pageData,u as default};
